  section.fills = [{ type: 'SOLID', color: { r: 0.969, g: 0.973, b: 0.98 } }];
  section.appendChild(target);
  target.x = HOST_PAD;
  target.y = HOST_PAD;
  section.resizeWithoutConstraints(target.width + HOST_PAD * 2, target.height + HOST_PAD * 2);
  section.x = 100;
  section.y = 100;
